using System.Collections.Generic;

// Crear un Stack de strings (historial de estados)
Stack<string> historial = new Stack<string>();

// Push — agrega al tope
historial.Push("Estado1");   // tope: Estado1
historial.Push("Estado2");   // tope: Estado2
historial.Push("Estado3");   // tope: Estado3

// Peek — lee el tope SIN eliminar
string tope = historial.Peek(); // "Estado3", el stack no cambia
Debug.Log(historial.Count);     // 3

// Pop — elimina y devuelve el tope
string ultimo = historial.Pop(); // devuelve "Estado3"
Debug.Log(historial.Count);      // 2 — ya solo tiene Estado1, Estado2

// Verificar si está vacío antes de Pop
if (historial.Count > 0)
{
    string anterior = historial.Pop(); // "Estado2"
}

